from collections import deque

def transform(grid):
    h,w=len(grid),len(grid[0]); bg=grid[0][0]
    outside=set(); q=deque()
    for r in range(h):
        for c in (0,w-1):
            if grid[r][c]==bg and (r,c) not in outside: outside.add((r,c)); q.append((r,c))
    for c in range(w):
        for r in (0,h-1):
            if grid[r][c]==bg and (r,c) not in outside: outside.add((r,c)); q.append((r,c))
    while q:
        r,c=q.popleft()
        for rr,cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0<=rr<h and 0<=cc<w and grid[rr][cc]==bg and (rr,cc) not in outside:
                outside.add((rr,cc)); q.append((rr,cc))
    enclosed={(r,c) for r in range(h) for c in range(w) if grid[r][c]==bg and (r,c) not in outside}
    out=[row[:] for row in grid]
    if enclosed:
        rs=[r for r,c in enclosed]; cs=[c for r,c in enclosed]
        # Color the central cell of the enclosed cavity with marker 4.
        r=(min(rs)+max(rs))//2; c=(min(cs)+max(cs))//2
        out[r][c]=4
    return out

